def icon(name, cls="", width=None):
    extra = f' class="i-{name} {cls}"'.replace(" \"", "\"")
    return (
        f'<svg{extra} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="{width or 1.8}" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{PATHS[name]}</svg>'
    )
